function constructionFeedback(c:Cell){const current=jobs?.displayCity??city,p=current.placement(c,tool),t=current.tile(c),growth=t.zone?current.buildingStatus(c):null;let message=p.reason+(p.cost?' / 費用 '+p.cost:'');if(growth)message+=' / '+(clock.speed===0?'一時停止中：時間を進めてください / ':'')+(growth.reasons.length?growth.reasons.join('・'):'建設・成長の準備 '+growth.age+'/'+growth.months+'か月 / 必要費 '+growth.cost);if(current.management?.lifecycle?.settlementPending)message+=' / 初期入居は住宅1棟分。商業・工業で雇用を作りましょう。';if(tool!=='select'&&(!history.supports(current,tool)||(tool==='erase'&&(t.facility||current.transit.stopAt(c.z*current.size+c.x)))))message+=' / 取り消し対象外';text('build-feedback',message);return p;}
function describe(c:Cell) { if(city.updating)return `X ${c.x} / Z ${c.z} · 都市更新中（確定後に操作を反映）`;const t=city.tile(c),r=city.safety.results.get(c.z*city.size+c.x);const safetyInfo=r?' / 消防 '+Math.round(r.fire*100)+'% '+(r.fireMinutes===null?'到達不可':fmt(r.fireMinutes)+'分')+' / 治安 '+Math.round((1-r.crimeRisk)*100)+'% 警察 '+Math.round(r.police*100)+'%':'';if(city.hydrology?.river.has(c.z*city.size+c.x))return `X ${c.x} / Z ${c.z} · 河川（建築不可）`;return `X ${c.x} / Z ${c.z} · ${t.road?(((city.network.isMain(c.z*city.size+c.x)?'幹線道路':'孤立道路')+' / 交通 '+city.traffic.volume(c.z*city.size+c.x)+' / 容量 '+city.traffic.capacity(c.z*city.size+c.x)+' / 混雑 '+Math.round(city.traffic.congestion(c.z*city.size+c.x)*100)+'%')):t.facility?names[t.facility]+' · '+(t.networkConnected?'稼働':'孤立'):t.zone?names[t.zone]+' Lv.'+t.level+' · '+(t.networkConnected?'幹線接続 / 稼働 '+Math.round(city.powerRatio*100)+'%':t.connected?'孤立道路に隣接':'未接続'):'未開発'}`; }
